              placeholder="${placeholder}"
              ${required ? 'required' : ''}
              ${autocomplete ? `autocomplete="${autocomplete}"` : ''}
              ${inputmode ? `inputmode="${inputmode}"` : ''}
              aria-describedby="${id}-help ${id}-error"
            />
            <p class="helper" id="${id}-help">${helperText || ""}</p>
            <p class="error" id="${id}-error" role="alert" aria-live="polite"></p>
          </div>
        `;
      }

      function App() {
        return `
          <main class="page">
            <section class="card" aria-labelledby="support-title">
              <header class="hero">
                <p class="eyebrow">Support</p>
                <h1 id="support-title">Contact our team</h1>
                <p class="subtitle">Send us a message and we’ll get back to you as soon as possible. Share the details below so we can help faster.</p>
              </header>

              <form id="contact-form" novalidate>
                <div class="form-grid">
                  ${Field({
                    id: "fullName",
                    label: "Full name",
                    type: "text",
                    placeholder: "Jane Doe",
                    required: true,
                    autocomplete: "name",
                    errorText: "Please enter your full name."
                  })}
                  ${Field({
                    id: "email",
                    label: "Email address",
                    type: "email",
                    placeholder: "jane@company.com",
                    required: true,
                    autocomplete: "email",
                    errorText: "Enter a valid email address."
                  })}
