       document.getElementById("app").innerHTML = App();

       const form = document.getElementById("contact-form");
       const status = document.getElementById("form-status");
       const fields = {
         fullName: document.getElementById("fullName"),
         email: document.getElementById("email"),
         phone: document.getElementById("phone")
       };

       const phonePattern = /^\+?[0-9\s().-]{7,}$/;

       function setError(input, message) {
         const errorEl = document.getElementById(`${input.id}-error`);
         input.setAttribute("aria-invalid", message ? "true" : "false");
         errorEl.textContent = message || "";
       }

       function validateField(input) {
         const value = input.value.trim();

         if (input.id === "fullName") {
           if (!value) return "Please enter your full name.";
           if (value.length < 2) return "Enter your full name.";
           return "";
         }

         if (input.id === "email") {
           if (!value) return "Please enter your email address.";
           if (!input.validity.valid) return "Enter a valid email address.";
           return "";
         }

         if (input.id === "phone") {
           if (!value) return "";
           if (!phonePattern.test(value)) return "Enter a valid phone number or leave it blank.";
           return "";
         }

         return "";
       }

       Object.values(fields).forEach((input) => {
         input.addEventListener("blur", () => {
           setError(input, validateField(input));
         });

         input.addEventListener("input", () => {
           if (input.getAttribute("aria-invalid") === "true") {
             setError(input, validateField(input));
           }
           status.textContent = "";
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const errors = {
           fullName: validateField(fields.fullName),
           email: validateField(fields.email),
           phone: validateField(fields.phone)
         };

         Object.entries(errors).forEach(([key, message]) => setError(fields[key], message));

         const firstInvalid = Object.keys(errors).find((key) => errors[key]);
         if (firstInvalid) {
           fields[firstInvalid].focus();
           status.textContent = "Please fix the highlighted fields.";
           return;
         }

         status.textContent = "Your request is ready to submit.";
         form.reset();
         Object.values(fields).forEach((input) => setError(input, ""));
       });
     </script>
